// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Reverter adversary;

    function setUp() public {
        c = new ReentrancyDAO();
        adversary = new Reverter();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        address actor = address(adversary);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        assertEq(address(c).balance, amount);

        uint256 before = address(c).balance;
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: any non-reverting withdrawAll must actually transfer the
        // credit out of the contract; otherwise it must revert.
        assertTrue(!ok || address(c).balance == before - amount);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
